import{_ as o,l as r,o as e,c as n,v as t,p as s,x as i,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"畸变","description":"","frontmatter":{"title":"畸变","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/distortion-field.md","filePath":"litho/distortion-field.md","lastUpdated":1789023840000}'),E={name:"litho/distortion-field.md"};function B(c,a,_,m,A,S){const l=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="畸变" tabindex="-1">畸变 <a class="header-anchor" href="#畸变" aria-label="Permalink to &quot;畸变&quot;">​</a></h1><div class="epigraph"><p>像散还在把点拉成焦线；畸变不增加糊斑，只让理想像点按视场挪位——桶形或枕形一次写进套刻指纹。</p><footer>—— Levinson, Principles of Lithography 对光学畸变与套刻的表述</footer></div><p><a href="/litho/astigmatism-field">上一课</a>把 H/V 焦线与场曲钉死。缺口是：<strong>即使落在当地最佳焦面上，像点仍可能不在高斯位置</strong>。本课只谈畸变（Seidel \\(S_V\\)）如何进套刻。把整瞳 RMS 收成衍射极限判据，留给<a href="/litho/strehl-ratio">Strehl 比</a>。不要从瑞利 CD 重讲，也不要引用未公开的镜头畸变残差图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>初级畸变波前对孔径是倾斜（\\(\\propto\\rho\\cos\\phi\\)），系数随视场三次方涨：每个场点看见的是当地倍率误差，不是模糊。桶形：边缘倍率小于近轴；枕形相反。光刻扫描场要的是栅格仍是栅格；畸变把矩形拉成枕或桶，层与层之间若指纹不同，套刻超标——即使两层的 NILS 都合格。缺口因此是这条<strong>位置误差</strong>，而不是再劈一次焦线。</p><p>远心也是倾斜项，但远心的倾斜随离焦才变成 \\(\\Delta x\\)；畸变在 \\(z=0\\) 已经在。场曲改的是哪一个 \\(z\\) 最好，不改高斯点的径向放大率（到初级）。</p><h3 id="畸变不是-cd-误差" tabindex="-1">畸变不是 CD 误差 <a class="header-anchor" href="#畸变不是-cd-误差" aria-label="Permalink to &quot;畸变不是 CD 误差&quot;">​</a></h3><p>阈值等高线的宽度由 NILS 与剂量决定；畸变把整条等高线平移。计量若用同一套标记既报 CD 又报套刻，要把「图形变胖」和「图形搬家」拆开。Levinson 把畸变放进套刻光学桶，与工件台、晶圆变形并列。</p><p><span class="marginnote">扫描方向上狭缝积分把静态枕形收成一条有效畸变。报指纹必须声明是静态透镜还是扫描平均后的晶圆结果。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对视场网格量或仿真像点位移 \\((\\Delta x,\\Delta y)\\)，拟合到 Seidel 畸变或高阶多项式（以及可补偿的放大、旋转、非正交）。镜头操纵能吃掉一部分低阶；吃不掉的高阶进套刻模型或进层间匹配。本课不列机台补偿器名单。</p><p>波前语言：畸变是场相关的 \\(Z_2\\)、\\(Z_3\\)（倾斜），与远心那对倾斜同形、场依赖不同。拟合时要把「全局放大」与「三次畸变」分开，否则对准模型会把光学指纹当成晶圆膨胀。</p><h3 id="与套刻标记的空间频率" tabindex="-1">与套刻标记的空间频率 <a class="header-anchor" href="#与套刻标记的空间频率" aria-label="Permalink to &quot;与套刻标记的空间频率&quot;">​</a></h3><p>标记通常比器件稀疏。畸变本身与频率无关——它是几何点的搬家。但若标记落在场内与器件不同的位置，读到的套刻不是器件处的畸变。高阶指纹下「标记合格、器件不合格」可以是采样问题，不一定是彗差。</p><p><span class="marginnote">浸没与干式、或两台镜头之间的畸变指纹不同，是层间套刻的经典光学项。匹配靠补偿与选场，不靠再加大 \\(\\mathrm{NA}\\)。</span></p>',15)),(e(),s(p,null,{default:i(()=>[d(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20AST%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E7%B3%8A%E4%B8%8E%E5%8A%88%E7%84%A6%22%5D%20--%3E%20DIST%5B%22%E7%95%B8%E5%8F%98%EF%BC%9A%E5%9C%BA%E7%9B%B8%E5%85%B3%E5%80%8D%E7%8E%87%22%5D%0A%20%20DIST%20--%3E%20SHIFT%5B%22%E5%83%8F%E7%82%B9%E5%B9%B3%E7%A7%BB%EF%BC%8C%E6%A0%B8%E4%B8%8D%E7%B3%8A%22%5D%0A%20%20SHIFT%20--%3E%20OV%5B%22%E5%A5%97%E5%88%BB%E6%8C%87%E7%BA%B9%22%5D%0A%20%20SCAN%5B%22%E7%8B%AD%E7%BC%9D%E6%89%AB%E6%8F%8F%E5%B9%B3%E5%9D%87%22%5D%20--%3E%20OV%0A%20%20OV%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AStrehl%20%E5%88%A4%E8%A1%8D%E5%B0%84%E6%9E%81%E9%99%90%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>孔径上的线性相位使像平移，平移量随 \\(H^3\\) 变，网格被非线性拉伸。强度点扩散的宽度（球差、像散、彗差决定）可以仍然接近衍射极限，Strehl 下一课可以很高，套刻却已经超标——这正是畸变必须单独成课的原因：对比判据看不见它。</p><p>扫描机沿狭缝扫过不同 \\(H\\)，瞬时畸变被时间平均。有效指纹比静态透镜平滑，但残留的高阶项仍在。热漂移让指纹随负荷变，与 Zernike 课的加热补偿是同一类控制，通道不同。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到套刻光学指纹、桶/枕、层间匹配，先问畸变（静态与扫描平均），再问远心 \\(\\alpha\\Delta z\\) 与彗差假套刻。Strehl 与 MTF 不替代本课。下一课用 RMS 波前谈「还能不能叫衍射极限」，默认已经把不糊的搬家拆走。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不含晶圆热膨胀、不含对准算法的高阶模型细节。那些会与光学畸变相加，定义仍是投影几何的场相关倍率。禁止编造未公开的纳米畸变图；Levinson 的预算分类与 Seidel \\(S_V\\) 已经够用。EUV 物方斜入射的阴影位移是掩模三维，不要全部记成投影畸变。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>畸变改像点位置，不增加糊斑；初级项随视场三次方。</li><li>直接进套刻指纹；与 CD / NILS 分桶。</li><li>\\(z=0\\) 已存在，不同于远心的 \\(\\alpha\\Delta z\\)。</li><li>扫描平均改变有效指纹，须声明读图条件。</li><li>整瞳是否衍射极限，下一课用 Strehl。</li><li>出处：Levinson, <em>Principles of Lithography</em>；Seidel 畸变见 Born &amp; Wolf。</li></ul>',9))])}const D=o(E,[["render",B]]);export{u as __pageData,D as default};
